previewCss:
.darma-loader-darma-b15-spray-can-shake { --accent: var(--loader-color, #7c3aed); --accent-2: var(--loader-secondary-color, #c4b5fd); width: var(--loader-size, 116px); height: calc(var(--loader-size, 116px) * .9); position: relative; }
.darma-loader-darma-b15-spray-can-shake .darma-loader-darma-b15-spray-can-shake__can { position: absolute; left: 12%; bottom: 8%; width: 32%; height: 60%; border-radius: 7px; background: linear-gradient(90deg, var(--accent), var(--accent-2) 60%, var(--accent)); animation: darma-loader-darma-b15-spray-can-shake-spray-shake calc(var(--loader-speed, 1s) * .42) ease-in-out infinite; }
.darma-loader-darma-b15-spray-can-shake .darma-loader-darma-b15-spray-can-shake__can::before { content: ''; position: absolute; left: 24%; width: 52%; bottom: 100%; height: 20%; border-radius: 3px 3px 0 0; background: #94a3b8; }
.darma-loader-darma-b15-spray-can-shake i { position: absolute; left: 48%; top: 20%; width: 10%; height: 10%; border-radius: 50%; background: var(--accent); opacity: 0; animation: darma-loader-darma-b15-spray-can-shake-spray-mist calc(var(--loader-speed, 1s) * 1.5) ease-out infinite; }
.darma-loader-darma-b15-spray-can-shake i:nth-of-type(1) { --dy: -30%; }
.darma-loader-darma-b15-spray-can-shake i:nth-of-type(2) { --dy: 40%; animation-delay: calc(var(--loader-speed, 1s) * .18); }
.darma-loader-darma-b15-spray-can-shake i:nth-of-type(3) { --dy: 110%; animation-delay: calc(var(--loader-speed, 1s) * .36); }
.darma-loader-darma-b15-spray-can-shake i:nth-of-type(4) { --dy: 175%; animation-delay: calc(var(--loader-speed, 1s) * .54); }
@keyframes darma-loader-darma-b15-spray-can-shake-spray-shake { 0%, 100% { transform: translate(0, 0) rotate(0deg); } 25% { transform: translate(-4%, -3%) rotate(-4deg); } 75% { transform: translate(4%, 3%) rotate(4deg); } }
@keyframes darma-loader-darma-b15-spray-can-shake-spray-mist { 0% { opacity: 0; transform: translate(0, 0) scale(.35); } 20% { opacity: .85; } 100% { opacity: 0; transform: translate(320%, var(--dy, 0%)) scale(1.6); } }

